1	export type QuoteResult = {
2	  premium: number;
3	};
4	
5	export type ScenarioOutcome = {
6	  results: QuoteResult[];
7	};
8	
9	type Item = { type: string; cursed?: boolean; enchantment?: number };
10	
11	type Customer = { yearsWithMHPCO: number };
12	
13	type Scenario = {
14	  customer: Customer;
15	  steps: { items: Item[] }[];
16	};
17	
18	const PROCESSING_FEE = 5;
19	const FIRST_INSURANCE_SURCHARGE = 0.1;
20	const CURSE_SURCHARGE = 0.5;
21	const HIGH_ENCHANTMENT_THRESHOLD = 5;
22	const HIGH_ENCHANTMENT_SURCHARGE = 0.3;
23	const LOYALTY_THRESHOLD_YEARS = 2;
24	const LOYALTY_DISCOUNT = 0.2;
25	const FOLLOW_UP_CONTRACT_DISCOUNT = 0.15;
26	
27	const BASE_PREMIUMS: Record<string, number> = {
28	  sword: 100,
29	  amulet: 60,
30	  staff: 80,
31	  potion: 40,
32	  rune: 25,
33	  moonstone: 25,
34	};
35	
36	const ALIKE_BLOCK_SIZE = 3;
37	const ALIKE_BLOCK_PREMIUM = 60;
38	
39	type AlikeGroup = [type: string, count: number];
40	
41	const groupAlikeItems = (items: Item[]): AlikeGroup[] => {
42	  const countByType = new Map<string, number>();
43	
44	  for (const item of items) {
45	    countByType.set(item.type, (countByType.get(item.type) ?? 0) + 1);
46	  }
47	
48	  return [...countByType];
49	};
50	
51	const basePremiumOfType = (type: string): number => BASE_PREMIUMS[type];
52	
53	const ownBasePremiumOf = (item: Item): number => basePremiumOfType(item.type);
54	
55	const basePremiumOfGroup = ([type, count]: AlikeGroup): number => {
56	  if (count === ALIKE_BLOCK_SIZE) return ALIKE_BLOCK_PREMIUM;
57	
58	  return count * basePremiumOfType(type);
59	};
60	
61	/**
62	 * The policy base premium: the sum of the item base premiums, with the
63	 * alike-block discount applied. Policy-scope modifiers are percentages OF
64	 * THIS amount — never of a total that already includes item surcharges.
65	 */
66	const policyBasePremiumOf = (items: Item[]): number =>
67	  groupAlikeItems(items)
68	    .map(basePremiumOfGroup)
69	    .reduce((total, groupPremium) => total + groupPremium, 0);
70	
71	/**
72	 * Item-scope surcharges: each is a percentage of the affected item's OWN base
73	 * premium, independent of the policy base and of the alike-block discount.
74	 */
75	const isCursed = (item: Item): boolean => item.cursed === true;
76	
77	const isHighlyEnchanted = (item: Item): boolean =>
78	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD;
79	
80	const itemSurchargeRateOf = (item: Item): number =>
81	  (isCursed(item) ? CURSE_SURCHARGE : 0) +
82	  (isHighlyEnchanted(item) ? HIGH_ENCHANTMENT_SURCHARGE : 0);
83	
84	const itemSurchargesOf = (items: Item[]): number =>
85	  items.reduce(
86	    (total, item) => total + ownBasePremiumOf(item) * itemSurchargeRateOf(item),
87	    0,
88	  );
89	
90	/**
91	 * Policy-scope modifiers: each is a percentage of the policy base premium.
92	 * Surcharges and discounts are netted into a single rate, so the policy base is
93	 * multiplied exactly once — this keeps the result free of the rounding drift
94	 * that separate discount and surcharge terms would introduce. The netted rate
95	 * (and hence the returned amount) is negative when the discounts outweigh the
96	 * surcharges.
97	 */
98	const isLongStanding = (customer: Customer): boolean =>
99	  customer.yearsWithMHPCO >= LOYALTY_THRESHOLD_YEARS;
100	
101	const policyModifierRateOf = (customer: Customer, isFollowUp: boolean): number =>
102	  FIRST_INSURANCE_SURCHARGE -
103	  (isLongStanding(customer) ? LOYALTY_DISCOUNT : 0) -
104	  (isFollowUp ? FOLLOW_UP_CONTRACT_DISCOUNT : 0);
105	
106	const policyModifiersOn = (
107	  policyBase: number,
108	  customer: Customer,
109	  isFollowUp: boolean,
110	): number => policyBase * policyModifierRateOf(customer, isFollowUp);
111	
112	const quotePremium = (items: Item[], customer: Customer, isFollowUp: boolean): number => {
113	  const policyBase = policyBasePremiumOf(items);
114	  const premium =
115	    policyBase +
116	    itemSurchargesOf(items) +
117	    policyModifiersOn(policyBase, customer, isFollowUp) +
118	    PROCESSING_FEE;
119	
120	  return Math.ceil(premium);
121	};
122	
123	export const runScenario = (scenario: Scenario): ScenarioOutcome => ({
124	  results: scenario.steps.map((step, index) => ({
125	    premium: quotePremium(step.items, scenario.customer, index > 0),
126	  })),
127	});
