const policyModifierRateOf = (customer: Customer, isFollowUp: boolean): number =>
  FIRST_INSURANCE_SURCHARGE -
  (isLongStanding(customer) ? LOYALTY_DISCOUNT : 0) -
  (isFollowUp ? FOLLOW_UP_CONTRACT_DISCOUNT : 0);

const policyModifiersOn = (
  policyBase: number,
  customer: Customer,
  isFollowUp: boolean,
): number => policyBase * policyModifierRateOf(customer, isFollowUp);

const quotePremium = (items: Item[], customer: Customer, isFollowUp: boolean): number => {
  const policyBase = policyBasePremiumOf(items);
  const premium =
    policyBase +
    itemSurchargesOf(items) +
    policyModifiersOn(policyBase, customer, isFollowUp) +
    PROCESSING_FEE;

  return Math.ceil(premium);
};

export const runScenario = (scenario: Scenario): ScenarioOutcome => ({
  results: scenario.steps.map((step, index) => ({
    premium: quotePremium(step.items, scenario.customer, index > 0),
  })),
});

